                val = True
            elif raw == 'false':
                val = False
            elif isinstance(raw, str) and raw.lstrip().startswith(('[', '{')):
                val = dec(raw)
            branch[parts[-1]] = val
        if isinstance(tree.get('cards'), dict):
            tree['cards'] = [tree['cards'][k] for k in sorted(tree['cards'], key=lambda x: int(x))]
        return tree
    keys = ['u_kind', 'u_card', 'u_digits', 'u_digit_mode', 'u_detail', 'u_followup', 'u_currency', 'u_period', 'u_week', 'u_destination']
