    for key, target, values in [('u_detail', 'wanted_detail', ['all', 'due', 'minimum', 'total']), ('u_followup', 'pending_followup', ['email', 'week']), ('u_currency', 'wanted_currency', codes + ['unclear']), ('u_period', 'wanted_period', ['latest', 'older'])]:
        if supplied.get(key) in values:
