(key), str):\n            vars[key] = decode(vars[key])\n    def norm(value, rx=re):\n        return rx.sub(r'\\s+', ' ', str(value).replace('İ', 'i').replace('I', 'ı').lower()).strip()\n    def alias(value, normalize=norm, rx=re):\n        text = normalize(value)\n        text = rx.sub(r\"[’'](?:ım|im|um|üm|ı|i|u|ü|ın|in|un|ün)$\", '', text)\n        text = rx.sub(r'\\b(?:benim|olanı|olanın|olan|kredi|kartımın|kartım|kartının|kartınızın|kartını|kartı|kart|ekstre|ekstresi|ekstrem|ekstremin|borcunu|borcum|borcumu|borcu)\\b', ' ', text)\n        return normalize(text).strip(' .?!,;:')\n    def total_only(text, normalize=norm, rx=re):\n        value = normalize(text)\n        restricted = bool(rx.search(r'\\b(?:sadece|yalnız|yalnızca)\\b', value))\n        total = bool(rx.search(r'\\btoplam(?:ı|ını|ım|ımı)?\\b|gelecek dönemler dahil|cari bor', value))\n        return restricted and total\n    def number(value, one=ones, ten=tens):\n        n = int(value)\n        if n == 0:\n            return one[0]\n        parts = []\n        for scale, name in [(1000000000000, 'trilyon'), (1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin'), (1, '')]:\n            group, n = divmod(n, scale)\n            if not group:\n                continue\n            if group >= 1000:\n                raise ValueError('amount_range')\n            words = []\n            if group // 100:\n                if group // 100 > 1:\n                    words.append(one[group // 100])\n                words.append('yüz')\n            rest = group % 100\n            if rest // 10:\n                words.append(ten[rest // 10])\n            if rest % 10:\n                words.append(one[rest % 10])\n            if scale == 1000 and group == 1:\n                words = []\n            if name:\n                words.append(name)\n            parts.extend(words)\n        return ' '.join(parts)\n    def minor(value, rx=re):\n        if isinstance(value, bool):\n            raise ValueError('invalid_amount')\n        text = str(value).strip().lower()\n        if not rx.fullmatch(r'-?\\d+(?:\\.\\d+)?(?:e[+-]?\\d+)?', text):\n            raise ValueError('invalid_amount')\n        negative = text.startswith('-')\n        text = text.lstrip('-')\n        exponent = 0\n        if 'e' in text:\n            text, exp = text.split('e')\n            exponent = int(exp)\n        bits = text.split('.')\n        digits = bits[0] + (bits[1] if len(bits) > 1 else '')\n        position = len(bits[0]) + exponent\n        if position < 0:\n            digits = '0' * (-position) + digits\n            position = 0\n        if position > len(digits):\n            digits += '0' * (position - len(digits))\n        fraction = digits[position:]\n        if len(fraction) > 2 and any(c != '0' for c in fraction[2:]):\n            raise ValueError('unsupported_precision_no_rounding')\n        amount = int(digits[:position] or '0') * 100 + int((fraction + '00')[:2])\n        return -amount if negative else amount\n    def money(value, currency, cv=minor, nw=number, names=labels, currencies=codes):\n        amount = cv(value)\n        if amount < 0:\n            raise ValueError('negative_debt_speech')\n        whole, fraction = divmod(amount, 100)\n        unit = 'kuruş' if currency == 'TL' else ('peni' if currency == 'GBP' else 'sent')\n        return nw(whole) + ' ' + names[currencies.index(currency)] + ((' ' + nw(fraction) + ' ' + unit) if fraction else '')\n    def date_value(text, dt=datetime):\n        return dt.datetime.strptime(str(text), '%d.%m.%Y').date()\n    def date_speech(text, parse=date_value, names=months):\n        value = parse(text)\n        return str(value.day) + ' ' + names[value.month - 1] + ' ' + str(value.year)\n    def safe_name(value, rx=re):\n        text = str(value or '').strip()\n        return '' if rx.search(r'talimat|yok say|ignore|system|prompt|numarasını oku|\\d[\\d *-]{5,}\\d', text, rx.I) else text\n    def intro(card, sn=safe_name, digits=ones):\n        last = str(card.get('cardNumberLast4', ''))\n        if len(last) != 4 or not last.isdigit():\n            raise ValueError('missing_last_four')\n        name = sn(card.get('productName', ''))\n        return 'Sonu ' + ' '.join(digits[int(c)] for c in last) + ' ile biten ' + (name + ' ' if name else '')\n    def joined(items):\n        if not items:\n            return ''\n        return items[0] if len(items) == 1 else ', '.join(items[:-1]) + ' ve ' + items[-1]\n    def eligible(card):\n        return isinstance(card, dict) and card.get('status') == 'A' and str(card.get('isMainCard')).lower() == 'true'\n    def authorized(v=vars, el=eligible):\n        card = v.get('selected_card', {})\n        return v.get('cards_ready') == 'yes' and v.get('cards_customer') == str(v.get('customerNumber', '')) and card in v.get('cards_private', []) and el(card) and v.get('balance_ready') == 'yes' and v.get('balance_card') == card.get('cardNumber')\n    def name_matches(cards, reference, normalize=norm, normalize_alias=alias):\n        ref = normalize_alias(reference)\n        exact = [c for c in cards if normalize(c.get('productName', '')) == normalize(reference)]\n        return exact or [c for c in cards if ref and set(ref.split()).issubset(set(normalize_alias(c.get('productName', '')).split()))]\n    def reference_matches(cards, reference, fragment, nm=name_matches, rx=re):\n        matches = nm(cards, reference) if reference else list(cards)\n        if fragment:\n            digits = rx.sub(r'[\\s-]', '', fragment)\n            if not digits.isdigit() or len(digits) not in [4, 6, 16]:\n                return []\n            selected = []\n            for card in matches:\n                key = str(card.get('cardNumber', ''))\n                part = key[-len(digits):] if len(digits) < 16 else key\n                if len(part) == len(digits) and all(a == '*' or a == b for a, b in zip(part, digits)):\n                    selected.append(card)\n            matches = selected\n        return matches\n    def question(phase, text, short='', key='', v=vars):\n        identity = key or phase\n        old = v.get('question_key', v.get('phase', ''))\n        if old != identity:\n            v['question_failures'] = 0\n        prefix = (str(v.get('notice_prefix', '')) + ' ' + str(v.get('reading_prefix', ''))).strip()\n        v['notice_prefix'] = ''\n        v['reading_prefix'] = ''\n        v['phase'] = phase\n        v['question_key'] = identity\n        v['speech'] = ((prefix + ' ') if prefix else '') + text.strip()\n        v['short_question'] = short or text.strip()\n        v['route'] = phase\n    def close(text, destination='main_menu', include_reading=False, v=vars):\n        prefix = str(v.get('notice_prefix', '')).strip()\n        if include_reading and v.get('reading_prefix'):\n            prefix = (prefix + ' ' + str(v['reading_prefix'])).strip()\n        v['notice_prefix'] = ''\n        v['reading_prefix'] = ''\n        v['phase'] = 'finished'\n        v['speech'] = ((prefix + ' ') if prefix else '') + text.strip()\n        v['short_question'] = ''\n        v['handoff_destination'] = destination\n        v['write_gate'] = 'no'\n        v['replay_input'] = {}\n        v['deferred_input'] = {}\n        v['arrival_input'] = {}\n        v['resume_state'] = {}\n        v['resume_confirmation'] = 'no'\n        v['after_contact'] = ''\n        v['route'] = 'finish'\n    def failure(v=vars, q=question, end=close):\n        v['question_failures'] = int(v.get('question_failures', 0)) + 1\n        if v['question_failures'] >= 3:\n            end('Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum.')\n        else:\n            q(v['phase'], v['short_question'], v['short_question'], v.get('question_key', v['phase']))\n    def card_prompt(cards, sn=safe_name, ins=intro):\n        choices = []\n        for card in cards:\n            name = sn(card.get('productName', '')) or ins(card).strip() + ' kart'\n            if name not in choices:\n                choices.append(name)\n        return 'Hangi kartınızın borcunu öğrenmek istersiniz?' + (' Örneğin, ' + ' veya '.join(choices[:2]) + ' diyebilirsiniz.' if choices else '')\n    def pick(card, v=vars):\n        if v.get('cards_customer') != str(v.get('customerNumber', '')) or card not in v.get('cards_private', []):\n            raise ValueError('selection_prerequisite')\n        v['selected_card'] = dict(card)\n        v['balance_ready'] = 'no'\n        v['week_ready'] = 'no'\n        v['preview_ready'] = 'no'\n        v['write_gate'] = 'no'\n        v['write_plan'] = {}\n        v['email_challenge'] = {}\n        v['week_challenge'] = {}\n        v['digits_buffer'] = ''\n        v['selection_candidates'] = []\n        v['selection_width'] = 4\n        v['selection_step'] = 'name'\n        v['reading_prefix'] = ''\n        v['email_question'] = ''\n        v['phase'] = 'balance_wait'\n        v['route'] = 'balance_lookup'\n    def week_allowed(card_key, v=vars):\n        return str(v.get('changed_years', {}).get(card_key, '')) != str(v['call_year']) and card_key not in v.get('claimed_used_cards', [])\n    def load_contact(next_phase, v=vars):\n        if v.get('contact_ready') == 'yes':\n            v['after_contact'] = ''\n            v['phase'] = next_phase\n        else:\n            v['after_contact'] = next_phase\n            v['phase'] = 'contact_wait'\n            v['route'] = 'contact_lookup'\n    def payload(value, prefix, v=vars, dec=decode):\n        data = dec(value) if value else {}\n        if isinstance(data, dict) and data:\n            return data\n        tree = {}\n        if not prefix:\n            return tree\n        for key, raw in v.items():\n            if not key.startswith(prefix):\n                continue\n            parts = key[len(prefix):].split('.')\n            branch = tree\n            for part in parts[:-1]:\n                branch = branch.setdefault(part, {})\n            val = raw\n            if raw == 'true':\n                val = True\n            elif raw == 'false':\n                val = False\n            elif isinstance(raw, str) and raw.lstrip().startswith(('[', '{')):\n                val = dec(raw)\n            branch[parts[-1]] = val\n        if isinstance(tree.get('cards'), dict):\n            tree['cards'] = [tree['cards'][k] for k in sorted(tree['cards'], key=lambda x: int(x))]\n        return tree\n    def current_list_warning(prefix, baseline, v=vars, js=json):\n        count = int(v.get(prefix + '_failure_count', 0) or 0)\n        seen = int(v.get(prefix + '_error_seen', 0) or 0)\n        if count <= max(int(baseline), seen):\n            return False\n        v[prefix + '_error_seen'] = count\n        transport = str(v.get(prefix + '_response.status', ''))\n        status = str(v.get(prefix + '_response.status_code') or v.get(prefix + '_status_code') or '')\n        if transport != 'error' or status != '404':\n            return False\n        bodies = []\n        raw_body = v.get(prefix + '_response.data', {})\n        if isinstance(raw_body, dict):\n            bodies.append(raw_body)\n        raw_result = v.get(prefix + '_response.data.result', {})\n        if isinstance(raw_result, dict) and raw_result:\n            bodies.append(dict(result=raw_result))\n        rc = str(v.get(prefix + '_response.data.result.returnCode', ''))\n        rt = str(v.get(prefix + '_response.data.result.type', ''))\n        if rc and rt:\n            bodies.append(dict(result=dict(returnCode=rc, code=str(v.get(prefix + '_response.data.result.code', '') or rc), type=rt)))\n        for raw in [raw_body, v.get(prefix + '_response.message', '')]:\n            if not isinstance(raw, str):\n                continue\n            for position, char in enumerate(raw):\n                if char != '{':\n                    continue\n                try:\n                    parsed, consumed = js.JSONDecoder().raw_decode(raw[position:])\n                    if isinstance(parsed, dict) and isinstance(parsed.get('result'), dict):\n                        bodies.append(parsed)\n                except ValueError:\n                    continue\n        for body in bodies:\n            outcome = body.get('result', {})\n            if isinstance(outcome, dict) and outcome.get('returnCode') == 'FB_IVR_CHANNEL_102' and outcome.get('code', 'FB_IVR_CHANNEL_102') == 'FB_IVR_CHANNEL_102' and outcome.get('type') == 'WARNING':\n                return True\n        return False\n    kinds = ['neutral', 'answer', 'yes', 'no', 'unclear', 'refuse', 'repeat', 'silence', 'agent', 'pay', 'dispute', 'third_party', 'non_turkish', 'outside', 'angry', 'privacy', 'secret', 'all_cards', 'card', 'email', 'week', 'done', 'stop', 'undo', 'effective', 'ai']\n    text_keys = ['u_card', 'u_digits', 'u_detail_request']\n    enums = dict(u_kind=kinds, u_digit_mode=['neutral', 'append', 'replace'], u_detail=['neutral', 'all', 'due', 'minimum', 'total'], u_followup=['neutral', 'email', 'week'], u_currency=['neutral', 'TL', 'USD', 'EUR', 'GBP', 'unclear'], u_period=['neutral', 'latest', 'older'], u_week=['neutral', '1', '2', '3', '4', 'invalid'], u_destination=['neutral', 'registered', 'other', 'wrong', 'paper', 'sms'])\n    keys = list(enums) + text_keys\n    def clean_input(raw, fields=keys, texts=text_keys, options=enums, normalize_alias=alias):\n        if not isinstance(raw, dict):\n            raw = dict(u_kind='unclear')\n        clean = {}\n        invalid = False\n        for name in fields:\n            value = raw.get(name, '' if name in texts else 'neutral')\n            if name in texts:\n                if not isinstance(value, str):\n                    invalid = True\n                    value = ''\n            elif value not in options[name]:\n                invalid = True\n                value = 'invalid' if name == 'u_week' else ('unclear' if name == 'u_currency' else 'neutral')\n            clean[name] = value\n        if clean['u_card'] and not normalize_alias(clean['u_card']):\n            clean['u_card'] = ''\n            if clean['u_kind'] == 'card' and not clean['u_digits']:\n                clean['u_kind'] = 'answer'\n        if invalid:\n            clean['u_kind'] = 'unclear'\n        return clean\n    supplied = clean_input(dict((key, vars.get(key, '' if key in text_keys else 'neutral')) for key in keys))\n    for key in keys:\n        vars[key] = '' if key in text_keys else 'neutral'\n    replay = decode(vars.get('replay_input', {}))\n    vars['replay_input'] = {}\n    if replay:\n        if any(supplied.get(k) not in ['', 'neutral'] for k in keys):\n            vars['deferred_input'] = dict(supplied)\n        supplied = clean_input(replay)\n    kind = supplied['u_kind']\n    incoming_phase = str(vars['phase'])\n    incoming_speech = str(vars['speech'])\n    event = str(vars.get('bank_event', '') or '')\n    pending = str(vars.get('bank_pending', '') or '')\n    event_status = str(vars.get('bank_status', 'fail'))\n    event_payload = vars.get('bank_payload', {})\n    vars['error_normalization'] = ''\n    if not event and pending:\n        event = pending\n        event_status = 'fail'\n        recovered = False\n        if pending == 'cards_list' and incoming_phase in ['start', 'list_wait'] and vars.get('request_valid') == 'yes' and vars.get('bank_status') == 'pending':\n            response_prefix = str(vars.get('bank_response_prefix') or ('lookup' if incoming_phase == 'list_wait' else 'cards_list'))\n            if response_prefix in ['cards_list', 'lookup']:\n                baseline = int(vars.get('list_failure_baseline', 0) or 0)\n                recovered = current_list_warning(response_prefix, baseline)\n        if recovered:\n            event_status = 'no_cards'\n            vars['error_normalization'] = 'current_cards_list_no_cards_warning'\n        else:\n            vars['diagnostic'] = 'RuntimeError: missing_bank_result'\n    vars['bank_event'] = ''\n    vars['bank_pending'] = ''\n    vars['bank_payload'] = {}\n    vars['bank_response_prefix'] = ''\n    vars['list_failure_baseline'] = 0\n    if event or pending:\n        vars['bank_status'] = 'idle'\n    vars['stale_event_ignored'] = ''\n    if event == 'cards_list' and vars.get('cards_ready') == 'yes' and vars.get('cards_customer') == str(vars.get('customerNumber', '')) and incoming_phase not in ['start', 'list_wait']:\n        vars['stale_event_ignored'] = event\n        event = ''\n    vars['operation_before_error'] = event or 'evaluate'\n    input_present = any(supplied.get(k) not in ['', 'neutral'] for k in keys)\n    initial_selection = vars.get('selection_initial') == 'yes'\n    vars['selection_initial'] = 'no'\n    arrival = decode(vars.get('arrival_input', {}))\n    if event == 'cards_list':\n        vars['arrival_input'] = {}\n        if arrival:\n            if input_present:\n                vars['deferred_input'] = dict(supplied)\n            supplied = clean_input(arrival)\n            kind = supplied['u_kind']\n            input_present = any(supplied.get(k) not in ['', 'neutral'] for k in keys)\n    request_text = supplied.get('u_detail_request', '').strip()\n    detail_value = supplied.get('u_detail', 'neutral')\n    if detail_value in ['all', 'due', 'minimum']:\n        vars['wanted_detail'] = detail_value\n        vars['detail_request'] = request_text\n    elif detail_value == 'total':\n        vars['wanted_detail'] = 'total' if total_only(request_text) else 'all'\n        vars['detail_request'] = request_text\n    elif request_text:\n        vars['detail_request'] = request_text\n        if total_only(request_text):\n            vars['wanted_detail'] = 'total'\n        elif re.search(r'ekstre|borc', norm(request_text)):\n            vars['wanted_detail'] = 'all'\n    if vars.get('wanted_detail') == 'total' and not total_only(vars.get('detail_request', '')):\n        vars['wanted_detail'] = 'all'\n    for key, target, values in [('u_followup', 'pending_followup', ['email', 'week']), ('u_currency', 'wanted_currency', codes + ['unclear']), ('u_period', 'wanted_period', ['latest', 'older'])]:\n        if supplied.get(key) in values:\n            vars[target] = supplied[key]\n    if supplied.get('u_destination') in ['registered', 'other', 'wrong', 'paper', 'sms']:\n        vars['destination_request'] = supplied['u_destination']\n    if kind == 'email':\n        vars['pending_followup'] = 'email'\n    elif kind == 'week' and incoming_phase in ['start', 'list_wait', 'choose_card', 'balance_wait', 'contact_wait', 'after_read']:\n        vars['pending_followup'] = 'week'\n    if supplied.get('u_week') in ['1', '2', '3', '4'] and incoming_phase not in ['week_choose', 'week_confirm']:\n        vars['early_week'] = int(supplied['u_week'])\n    now = datetime.datetime.fromisoformat(str(vars['now']))\n    today = now.date()\n    vars['call_year'] = str(today.year)\n    if not re.fullmatch(r'\\d{8}', str(vars.get('customerNumber', ''))):\n        raise ValueError('missing_trusted_customer')\n    result_handled = False\n    prefixes = dict(cards_list='lookup_response.data.data.', cards_balance='balance_lookup_response.data.data.', contact_email_get='contact_lookup_response.data.data.', statement_week_get='week_lookup_response.data.data.', statement_week_decide='preview_lookup_response.data.data.', statement_week_change='change_write_response.data.data.', statement_pdf_send='email_write_response.data.data.')\n    if event:\n        data = payload(event_payload, prefixes.get(event, '')) if event_status == 'ok' else {}\n        result_handled = True\n        vars['last_consumed_bank_event'] = event\n        if event == 'cards_list' and event_status == 'no_cards':\n            close('Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.')\n        elif event_status != 'ok':\n            message = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.' if event.startswith('statement_week_') else 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'\n            close(message, 'agent', True)\n        elif event == 'cards_list':\n            if 'cards' not in data:\n                raise ValueError('missing_cards_field')\n            cards = decode(data['cards'])\n            if not isinstance(cards, list) or any(not isinstance(c, dict) for c in cards):\n                raise ValueError('invalid_cards')\n            if 'validCardsCount' in data and int(data['validCardsCount']) != len(cards):\n                raise ValueError('inconsistent_card_count')\n            vars['cards_private'] = cards\n            vars['cards_customer'] = str(vars['customerNumber'])\n            vars['cards_ready'] = 'yes'\n            usable = [c for c in cards if eligible(c)]\n            if not usable:\n                close('Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.')\n            else:\n                vars['phase'] = 'choose_card'\n                initial_selection = True\n                result_handled = False\n                if len(usable) == 1 and not supplied.get('u_card') and not supplied.get('u_digits') and kind not in ['all_cards', 'secret']:\n                    pick(usable[0])\n                    result_handled = True\n        elif event == 'cards_balance':\n            card = vars['selected_card']\n            if vars.get('cards_ready') != 'yes' or vars.get('cards_customer') != str(vars['customerNumber']) or card not in vars.get('cards_private', []) or not eligible(card):\n                raise ValueError('balance_authorization')\n            vars['balance'] = data\n            vars['balance_card'] = card['cardNumber']\n            vars['balance_ready'] = 'yes'\n            sd = str(data.get('statementDate', ''))\n            due = str(data.get('lastPayDate', ''))\n            nxt = str(data.get('nextStatementDate', ''))\n            blocks = [(code, label, data.ge