    def payload(value, prefix, v=vars, dec=decode):
        data = dec(value) if value else {}
        if isinstance(data, dict) and data:
            return data
        tree = {}
        if not prefix:
            return tree
        for key, raw in v.items():
            if not key.startswith(prefix):
                continue
            parts = key[len(prefix):].split('.')
            branch = tree
            for part in parts[:-1]:
                branch = branch.setdefault(part, {})
            val = raw
            if raw == 'true':
                val = True
            elif raw == 'false':
                val = False
            elif isinstance(raw, str) and raw.lstrip().startswith(('[', '{')):
                val = dec(raw)
            branch[parts[-1]] = val
        if isinstance(tree.get('cards'), dict):
            tree['cards'] = [tree['cards'][k] for k in sorted(tree['cards'], key=lambda x: int(x))]
        return tree
    def safe_error_object(raw, v=vars, js=json, rx=re):
        try:
            if not isinstance(raw, str):
                return {}
            if len(raw) > 16384:
                v['error_parse_diagnostic'] = 'ValueError: cards_list_error_text_size_limit'
                return {}
            position = raw.find('{')
            if position < 0:
                return {}
            parts = []
            stack = []
            tokens = 0
            finished = False
            closing = dict([('}', '{'), (']', '[')])
            escapes = dict([('\\', '\\'), ("'", "'"), ('"', '"'), ('/', '/'), ('a', '\a'), ('b', '\b'), ('f', '\f'), ('n', '\n'), ('r', '\r'), ('t', '\t'), ('v', '\v')])
            literals = [('None', 'null'), ('True', 'true'), ('False', 'false'), ('null', 'null'), ('true', 'true'), ('false', 'false')]
            while position < len(raw):
                char = raw[position]
                if char.isspace():
                    position += 1
                    continue
                tokens += 1
                if tokens > 2048:
                    v['error_parse_diagnostic'] = 'ValueError: cards_list_error_text_token_limit'
                    return {}
                if char in ['{', '[']:
                    stack.append(char)
                    if len(stack) > 16:
                        v['error_parse_diagnostic'] = 'ValueError: cards_list_error_text_depth_limit'
                        return {}
                    parts.append(char)
                    position += 1
                elif char in closing:
                    if not stack or stack[-1] != closing[char]:
                        return {}
                    stack.pop()
                    parts.append(char)
                    position += 1
                    if not stack:
                        finished = True
                        break
                elif char in [':', ',']:
                    parts.append(char)
                    position += 1
                elif char in ["'", '"']:
                    quote = char
                    position += 1
                    letters = []
                    complete = False
                    while position < len(raw):
                        char = raw[position]
                        if char == quote:
                            position += 1
                            complete = True
                            break
                        if char == '\\':
                            position += 1
                            if position >= len(raw):
                                return {}
                            escape = raw[position]
                            if escape in escapes:
                                letters.append(escapes[escape])
                                position += 1
                            elif escape in ['x', 'u', 'U']:
                                width = 2 if escape == 'x' else (4 if escape == 'u' else 8)
                                hexadecimal = raw[position + 1:position + 1 + width]
                                if len(hexadecimal) != width or any(c not in '0123456789abcdefABCDEF' for c in hexadecimal):
                                    return {}
                                letters.append(chr(int(hexadecimal, 16)))
                                position += width + 1
                            else:
                                return {}
                        else:
                            if ord(char) < 32:
                                return {}
                            letters.append(char)
                            position += 1
                    if not complete:
                        return {}
                    parts.append(js.dumps(''.join(letters), ensure_ascii=True))
                else:
                    literal_found = False
                    for spelling, normalized in literals:
                        if raw.startswith(spelling, position):
                            parts.append(normalized)
                            position += len(spelling)
                            literal_found = True
                            break
                    if literal_found:
                        continue
                    match = rx.match(r'-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?', raw[position:])
                    if not match:
                        return {}
                    parts.append(match.group(0))
                    position += len(match.group(0))
            if not finished or stack:
                return {}
            def unique_object(pairs):
                value = {}
                for key, item in pairs:
                    if key in value:
                        raise ValueError('duplicate_error_field')
                    value[key] = item
                return value
            parsed = js.loads(''.join(parts), object_pairs_hook=unique_object)
            return parsed if isinstance(parsed, dict) else {}
        except Exception as exc:
            v['error_parse_diagnostic'] = str(type(exc)) + ': cards_list_error_text_parse'
            return {}
    def current_list_warning(prefix, baseline, v=vars, parse=safe_error_object):
        v['error_parse_diagnostic'] = ''
        count = int(v.get(prefix + '_failure_count', 0) or 0)
        seen = int(v.get(prefix + '_error_seen', 0) or 0)
        if count <= max(int(baseline), seen):
            return False
        v[prefix + '_error_seen'] = count
        transport = str(v.get(prefix + '_response.status', ''))
        status = str(v.get(prefix + '_response.status_code') or v.get(prefix + '_status_code') or '')
        if transport != 'error' or status != '404':
            return False
        bodies = []
        raw_body = v.get(prefix + '_response.data', {})
        if isinstance(raw_body, dict):
            bodies.append(raw_body)
        raw_result = v.get(prefix + '_response.data.result', {})
        if isinstance(raw_result, dict) and raw_result:
            bodies.append(dict(result=raw_result))
        rc = str(v.get(prefix + '_response.data.result.returnCode', ''))
        cc = str(v.get(prefix + '_response.data.result.code', ''))
        rt = str(v.get(prefix + '_response.data.result.type', ''))
        if rc and cc and rt:
            bodies.append(dict(result=dict(returnCode=rc, code=cc, type=rt)))
        for raw in [raw_body, v.get(prefix + '_response.message', '')]:
            if not isinstance(raw, str):
                continue
            parsed = parse(raw)
            if isinstance(parsed.get('result'), dict):
                bodies.append(parsed)
        for body in bodies:
            outcome = body.get('result', {})
            if isinstance(outcome, dict) and outcome.get('returnCode') == 'FB_IVR_CHANNEL_102' and outcome.get('code') == 'FB_IVR_CHANNEL_102' and outcome.get('type') == 'WARNING':
                return True
        return False
